// Business Central specifics shared by the extension host and the designer webview:
// the AL report context of a layout, preview parameters from labels/captions and BC-shaped sample data.

import type { Row } from './expr';
import { Field, Report } from './model';

export interface BcColumn {
  name: string;
  source: string;
  includeCaption: boolean;
  /** The layout's dataset (generated by the AL compiler at the last build) contains this column. */
  inLayout: boolean;
  line: number;
  character: number;
}
export interface BcDataItem { name: string; table: string; columns: BcColumn[]; children: BcDataItem[]; line: number; character: number }
export interface BcLabel { name: string; text: string; inLayout: boolean; line: number; character: number }

/** The AL report a layout belongs to, as sent to the webview. */
export interface BcContext {
  reportName: string;
  kind: 'report' | 'reportextension';
  id: number | null;
  /** Workspace-relative path of the AL file, for display. */
  alFile: string;
  alUri: string;
  /** Position of the report declaration in the AL file. */
  line: number;
  character: number;
  dataItems: BcDataItem[];
  labels: BcLabel[];
  /** Parameters generated for columns with IncludeCaption ("<Column>Caption"). */
  captions: { name: string; column: string; text: string; inLayout: boolean }[];
  /** False for a report extension whose base report is not in the workspace. */
  complete: boolean;
  /** Columns/labels the layout dataset lacks (project not built since they were added). */
  missingInLayout: string[];
  /** Fields/parameters in the layout dataset the AL report no longer defines. */
  removedInAl: string[];
}

/** A Business Central layout: has the dataset the AL compiler generates, or is linked to an AL report. */
export const isBcLayout = (r: Report, bc: BcContext | null) => !!bc || r.dataSets.some(d => d.name === 'DataSet_Result');

/**
 * Readable caption from a column's source expression, as the field caption would read:
 * `"No."` → "No.", `Customer."Phone No."` → "Phone No.", `CompanyProperty.DisplayName()` → "Display Name".
 */
export function captionFromSource(source: string): string {
  const quoted = /"([^"]+)"\s*$/.exec(source.trim());
  if (quoted) return quoted[1];
  const last = source.replace(/\(.*\)\s*$/, '').split('.').pop() ?? source;
  return last.replace(/_/g, ' ').replace(/([a-z\d])([A-Z])/g, '$1 $2').trim();
}

/**
 * Values for the report parameters in the preview. Business Central fills labels and captions at run time, so the
 * preview uses the label text from AL, the caption derived from the column source, the parameter default, or its name.
 */
export function previewParameters(r: Report, bc: BcContext | null): Record<string, string> {
  const fromAl = new Map<string, string>([
    ...(bc?.labels ?? []).map(l => [l.name, l.text] as [string, string]),
    ...(bc?.captions ?? []).map(c => [c.name, c.text] as [string, string]),
  ]);
  return Object.fromEntries(r.parameters.map(p => [p.name, fromAl.get(p.name) ?? (p.defaultValue || (isBcLayout(r, bc) ? p.prompt || p.name : ''))]));
}

const NUMERIC = /(amount|amt|qty|quantity|price|cost|balance|total|number|count|pct|percent|lineno|line_no|entryno|entry_no|discount|vat|rate|weight|volume)/i;

function value(f: { name: string; typeName: string }, record: number, item: string, numeric?: Set<string>): unknown {
  let t = f.typeName.replace(/^System\./, '').toLowerCase();
  if (!t) t = /format$/i.test(f.name) ? 'format' : numeric?.has(f.name) || NUMERIC.test(f.name) ? 'decimal' : /date/i.test(f.name) ? 'datetime' : /^(show|print|is|has)/i.test(f.name) ? 'boolean' : 'string';
  const seed = ((record + 1) * 7919 + f.name.length * 104729) % 1000;
  if (t === 'format') return '';
  if (/^(int|long|short|byte)/.test(t)) return /lineno|line_no/i.test(f.name) ? (record + 1) * 10000 : (seed % 100) + 1;
  if (/^(decimal|double|single|float)/.test(t)) return Math.round(seed * 13.37) / 10;
  if (t.startsWith('datetime') || t === 'date') {
    const d = new Date(2026, record % 12, (seed % 27) + 1);
    // without a type the field is text: Business Central sends dates already formatted
    return f.typeName ? d.toISOString() : d.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });
  }
  if (t === 'boolean') return record % 2 === 0;
  return `${item} ${record + 1}`;
}

/**
 * Sample rows shaped like a Business Central dataset: data items are flattened – every record of a data item gives a
 * row carrying its parents' columns; child columns stay empty on the parent's own row (which is why layouts filter
 * e.g. on line numbers). Two records per top-level item and three per child item.
 */
export function bcMockRows(bc: BcContext, fields: Field[], numeric?: Set<string>): Row[] {
  const typeOf = new Map(fields.map(f => [f.name, f.typeName]));
  const rows: Row[] = [];
  const emit = (items: BcDataItem[], inherited: Row, depth: number) => {
    for (const item of items) {
      const count = depth === 0 ? 2 : 3;
      for (let i = 0; i < count; i++) {
        const row: Row = { ...inherited };
        for (const c of item.columns) {
          row[c.name] = value({ name: c.name, typeName: typeOf.get(c.name) ?? '' }, i, item.name, numeric);
          if (typeOf.has(`${c.name}Format`)) row[`${c.name}Format`] = '';
        }
        rows.push(row);
        emit(item.children, row, depth + 1);
      }
    }
  };
  emit(bc.dataItems, {}, 0);
  // fields the AL tree does not know (stale layout) stay empty
  return rows;
}
